gND(){return"\u0628\u06d5\u062f\u0648\u06cc\u062f\u0627\u0686\u0648\u0648\u0646\u0627 \u0633\u06d5\u0631\u06d5\u062f\u0627\u0646\u06ce\u0646 \u0646\u0648\u06ce\u0646\u06d5\u0631\u0627\u0646"},
gNE(){return"\u0686\u06d5\u0646\u062f \u0631\u06c6\u0698 \u062f\u06a4\u06ce\u062a \u0698 \u062f\u0648\u0645\u0627\u0647\u06cc\u06a9 \u0633\u06d5\u0631\u06d5\u062f\u0627\u0646\u0627 \u0646\u0648\u06ce\u0646\u06d5\u0631\u06cc \u0628\u06c6 \u062f\u06a9\u062a\u06c6\u0631\u06d5\u06a9\u06cc \u062f\u06d5\u0631\u0628\u0627\u0632 \u0628\u0628\u0646 \u0647\u06d5\u062a\u0627 \u0626\u06d5\u0648 \u062f\u06a9\u062a\u06c6\u0631 \u062f\u0648\u0648\u0628\u0627\u0631\u06d5 \u0644 \u062a\u0627\u0628\u06ce \u0633\u06d5\u0631\u06d5\u062f\u0627\u0646\u0627\u0646 \u0648\u06d5\u06a9 \xab\u062f\u06d5\u0645\u06ce \u0648\u06cc \u0647\u0627\u062a\u06cc\xbb \u0646\u06cc\u0634\u0627\u0646 \u0628\u062f\u06d5\u062a."},
